// Integrator should merge dispatcher + .active-agent-state/control-loop-report.json
// This template shows exception filter logic only.
const body = $input.first().json;
const routings = Array.isArray(body.routings) ? body.routings : [];
const report = body.control_loop_report || {};
const recoveries = Array.isArray(report.recoveries) ? report.recoveries : [];
const summary = report.summary || {};

const exceptions = [];

for (const r of recoveries) {
  if (!r || r.action === 'none') continue;
  exceptions.push({ kind: 'control_loop_recovery', severity: r.action === 'blocker' ? 'urgent' : 'warning', message: r.message || r.reason, target: r.target });
}

if (summary.falseClaims > 0) {
  exceptions.push({ kind: 'false_claim', severity: 'urgent', message: `${summary.falseClaims} false claimed state(s)`, target: 'control-loop' });
}
if (summary.readyNeverActivated > 0) {
  exceptions.push({ kind: 'ready_never_activated', severity: 'warning', message: `${summary.readyNeverActivated} ready issue(s) never activated`, target: 'dispatcher' });
}

const blocked = routings.filter(r => r && r.gated === true && /protected|payment|production|merge/i.test(String(r.reason || r.recommendedNextAction || '')));
for (const b of blocked.slice(0, 3)) {
  exceptions.push({ kind: 'protected_decision', severity: 'urgent', message: b.recommendedNextAction || b.reason, target: b.objectRef });
}

const clientReady = routings.filter(r => r && /client.?ready|awaiting review/i.test(String(r.recommendedNextAction || '')));
for (const c of clientReady.slice(0, 2)) {
  exceptions.push({ kind: 'client_ready_review', severity: 'warning', message: c.recommendedNextAction, target: c.objectRef });
}

const shouldAlert = exceptions.length > 0;
const antonOnly = exceptions.some(e => e.severity === 'urgent');

return [{ json: {
  evaluated_at: new Date().toISOString(),
  exception_count: exceptions.length,
  exceptions: exceptions.slice(0, 8),
  should_alert: shouldAlert,
  anton_telegram: antonOnly,
  github_comment: shouldAlert && !antonOnly,
  silent_success: !shouldAlert,
} }];
